import sys
import subprocess
import shlex

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue
        elif line.startswith('cmd: '):
            cmd_part = line[5:].strip()
            try:
                result = subprocess.check_output(shlex.split(cmd_part), stderr=subprocess.STDOUT, text=True)
                print(result, end='')
            except subprocess.CalledProcessError as e:
                print(e.output, end='')
        elif line.startswith('expr: '):
            expr_part = line[6:].strip()
            try:
                value = eval(expr_part)
                print(value)
            except Exception:
                print('error: unrecognized directive', file=sys.stderr)
        else:
            print('error: unrecognized directive', file=sys.stderr)

if __name__ == '__main__':
    main()

